// 网关按路径前缀把请求路由到对应后端服务
const routes = [
  { prefix: "/api/orders", upstream: "order-svc:8080" },
  { prefix: "/api/pay", upstream: "payment-svc:8080" },
  { prefix: "/api/users", upstream: "user-svc:8080" },
];

function route(path) {
  const r = routes.find((x) => path.startsWith(x.prefix));
  return r ? r.upstream : "404-no-route";
}

console.log(route("/api/orders/123"));
console.log(route("/api/pay/capture"));
console.log(route("/api/users/me"));
console.log(route("/healthz"));
